"""audio.py: every sound is generated by code (no audio files). If there is no sound device the game still runs."""
import array
import math
import random
import pygame


class Audio:
    def __init__(self):
        self.ok = False
        self.sounds = {}
        self.enabled = True
        try:
            pygame.mixer.pre_init(22050, -16, 2, 512)
            pygame.mixer.init()
            self.rate, _, self.ch = pygame.mixer.get_init()
            self.ok = True
            self._build()
        except Exception:
            self.ok = False

    def _snd(self, samples):
        a = array.array("h")
        for v in samples:
            iv = int(max(-1.0, min(1.0, v)) * 32767)
            a.append(iv)
            if self.ch == 2:
                a.append(iv)
        return pygame.mixer.Sound(buffer=a.tobytes())

    def _build(self):
        R, rnd = self.rate, random.Random(2)
        n = lambda sec: int(R * sec)
        # heartbeat: two soft low thumps
        hb = [0.0] * n(0.55)
        for start, amp in ((0.0, 1.0), (0.2, 0.7)):
            for i in range(n(0.18)):
                t = i / R
                k = start and 1 or 1
                hb[i + n(start)] += amp * math.sin(2 * math.pi * (62 - 120 * t) * t) * math.exp(-t * 20)
        self.sounds["heart"] = self._snd([v * 0.9 for v in hb])
        # lantern found: a soft bell
        self.sounds["pickup"] = self._snd([(math.sin(2 * math.pi * 880 * i / R) * 0.5 + math.sin(2 * math.pi * 1318 * i / R) * 0.3 + math.sin(2 * math.pi * 1760 * i / R) * 0.15) * math.exp(-i / R * 4) * 0.5 for i in range(n(1.0))])
        # shadow hit: low rumble with a noise burst
        self.sounds["hit"] = self._snd([(math.sin(2 * math.pi * (90 - 60 * (i / R)) * i / R) * 0.8 + rnd.uniform(-1, 1) * 0.5 * math.exp(-i / R * 18)) * math.exp(-i / R * 5) for i in range(n(0.7))])
        # footsteps: two soft crunches
        for name, f in (("step1", 0.55), ("step2", 0.42)):
            lp, out = 0.0, []
            for i in range(n(0.1)):
                lp += (rnd.uniform(-1, 1) - lp) * f
                out.append(lp * math.exp(-i / R * 38) * 0.6)
            self.sounds[name] = self._snd(out)
        # out of breath
        lp, out = 0.0, []
        for i in range(n(0.6)):
            t = i / R
            lp += (rnd.uniform(-1, 1) - lp) * 0.2
            out.append(lp * math.sin(math.pi * t / 0.6) * 0.5)
        self.sounds["gasp"] = self._snd(out)
        # wind: slow noise that swells (loops)
        L = n(4.0)
        raw = [rnd.uniform(-1, 1) for _ in range(L)]
        sm, acc = [], 0.0
        for i in range(L):
            acc += (raw[i] - acc) * 0.02
            sm.append(acc * (0.6 + 0.4 * math.sin(2 * math.pi * i / L)) * 4.0)
        self.sounds["wind"] = self._snd(sm)
        self._wind = None

    def start_ambience(self):
        if self.ok and self._wind is None:
            self._wind = self.sounds["wind"].play(-1)
            if self._wind:
                self._wind.set_volume(0.18)

    def play(self, name, volume=1.0, pan=0.0):
        """pan: -1 = left ear ... +1 = right ear."""
        if not (self.ok and self.enabled) or name not in self.sounds:
            return
        ch = self.sounds[name].play()
        if ch:
            ch.set_volume(volume * (1 - max(0.0, pan)), volume * (1 + min(0.0, pan)))

    def toggle(self):
        self.enabled = not self.enabled
        if self._wind:
            self._wind.set_volume(0.18 if self.enabled else 0.0)
